import type { ParcelLinkConfig } from '@linm-soft-org/linm-web-common-components';
import type { CustomerDto } from '../../services/kt/models';

/** @deprecated Use `ParcelLinkConfig` from `@linm-soft-org/linm-web-common-components` */
export type SearchParcelLinkConfig = ParcelLinkConfig;

/** Customer quick-create — provider parcel entry `linm-erp-master-parcel.js` */
export const CUSTOMER_CREATE_PARCEL: ParcelLinkConfig = {
  moduleName: '@linm/erp-master-parcel',
  exportName: 'customerCreateParcelLifecycles',
  createLabel: 'Tạo mới khách hàng',
  modalTitle: 'Tạo mới khách hàng',
  hostVariant: 'slideout',
  slideoutWidth: '720px',
};

/** Prefill khi mở parcel Tạo mới (vd. import sao kê). */
export type CustomerCreatePrefill = {
  /** Ưu tiên hơn search term — tên đối tượng trên sao kê. */
  name?: string;
  bankAccountNumber?: string;
  bankName?: string;
};

/** Đồng bộ Master `CustomerCreateParcelResult`. */
export type CustomerCreateParcelResult = {
  customerId: string;
  code: string;
  name: string;
  phone?: string;
  customerType?: string;
  customerGroupId?: string;
  taxCode?: string;
  address?: string;
  accountCode?: string;
};

export type CustomerCreateParcelCustomProps = {
  initialName?: string;
  initialBankAccountNumber?: string;
  initialBankName?: string;
  defaultCustomerType?: string;
  onSuccess: (customer: CustomerCreateParcelResult) => void;
  onCancel: () => void;
};

/** Map parcel result → `CustomerDto` cho SearchInput / chứng từ. */
export function mapCustomerCreateResultToDto(
  created: CustomerCreateParcelResult,
  fallbackCustomerType?: string,
): CustomerDto {
  return {
    customerId: created.customerId,
    code: created.code ?? '',
    name: created.name ?? '',
    phone: created.phone,
    customerType: created.customerType ?? fallbackCustomerType,
    customerGroupId: created.customerGroupId,
    taxCode: created.taxCode,
    address: created.address,
    isActive: true,
  };
}
